CLAIMS=[
(971,"technique-relevance","网络拒绝服务通过攻击流量使链路、协议路径或边界容量无法承载合法通信；端点内部故障和攻击者任务带宽消费具有不同直接对象。","Network Denial of Service makes a link, protocol path, or boundary capacity unable to carry legitimate communications through attack traffic; endpoint-internal failure and bandwidth consumption for adversary work have different direct objects.",["NJT-0198"],["REF-000955","REF-000958","REF-000899"],"directly-observed","high"),
(972,"subtechnique-existence","分布式洪泛可让每个真实来源只贡献较小流量，而目的/中转汇聚后形成容量损失，要求跨来源和观察域聚合。","Distributed flooding can leave each real source contributing little traffic while destination or transit aggregation creates capacity loss, requiring cross-source and cross-domain aggregation.",["NJT-0198","NJS-0198-001","NM-ST"],["REF-000956","REF-000957","REF-000958"],"directly-observed","high"),
(973,"subtechnique-existence","攻击者可伪造受害者源地址驱动第三方服务向受害者回包，使可见来源成为合法响应者而不是真实发起者。","An attacker can spoof the victim source to drive third-party services to send responses to the victim, making visible origins legitimate responders rather than the true initiator.",["NJT-0198","NJS-0198-002","NM-FD"],["REF-000956","REF-000958","REF-000960"],"directly-observed","high"),
(974,"detection","多源低贡献洪泛检测需把 IPFIX 流与 IF-MIB 容量、丢弃和合法业务基线按目的、时间和来源拓扑聚合；单源阈值不足。","Detection of multi-source low-contribution flooding needs to aggregate IPFIX flow with IF-MIB capacity, discard, and legitimate-traffic baselines by destination, time, and source topology; per-source thresholds are insufficient.",["NJT-0198","NJS-0198-001","DET-000230"],["REF-000664","REF-000961","REF-000962"],"strongly-inferred","high"),
(975,"detection","反射响应检测需要证明受害者没有对应出站请求、入站响应来自多第三方且与伪造源/协议关系一致；合法大响应和 Anycast 需排除。","Reflection-response detection requires evidence that the victim sent no corresponding requests, responses arrive from many third parties, and traffic matches spoofed-source protocol behavior; legitimate large responses and Anycast require exclusion.",["NJT-0198","NJS-0198-002","DET-000230"],["REF-000958","REF-000960","REF-000664"],"strongly-inferred","high"),
(976,"mitigation","源地址验证、反射服务约束和上游清洗/吸收可减少反射与分布式洪泛，但依赖跨网络部署并可能影响合法突发。","Source-address validation, reflector-service constraints, and upstream scrubbing or absorption reduce reflection and distributed flooding but depend on cross-network deployment and can affect legitimate bursts.",["NJT-0198","NJS-0198-001","NJS-0198-002"],["REF-000959","REF-000960","REF-000963"],"strongly-inferred","high"),
(977,"technique-relevance","端点拒绝服务要求攻击输入造成端点、OS、服务或应用内部资源耗尽/故障并使合法功能实际不可用，区别于网络路径饱和和有序服务停止。","Endpoint Denial of Service requires adversary input to exhaust or fault internal endpoint, OS, service, or application resources and make legitimate function actually unavailable, distinct from path saturation and orderly service stop.",["NJT-0199"],["REF-000964","REF-000955","REF-000866"],"directly-observed","high"),
(978,"subtechnique-existence","低速不完整 HTTP 连接可用很少带宽长期占用连接或工作槽位，使完成请求日志和短窗口流量低估累计状态耗尽。","Slow incomplete HTTP connections can hold connection or worker slots for long periods with little bandwidth, causing completion logs and short-window traffic to underestimate accumulated state exhaustion.",["NJT-0199","NJS-0199-001","NM-ST"],["REF-000965","REF-000966","REF-000967"],"directly-observed","high"),
(979,"subtechnique-existence","精心构造的小输入可触发 ReDoS 等指数或异常内部工作，使请求外形和内部 CPU/事件循环代价失配。","Crafted small inputs can trigger exponential or anomalous internal work such as ReDoS, decoupling request appearance from CPU or event-loop cost.",["NJT-0199","NJS-0199-002","NM-FD"],["REF-000968","REF-000969","REF-000970"],"directly-observed","high"),
(980,"detection","状态保持耗尽检测需保留未完成连接、连接年龄、字节进度、活动/拒绝连接和外部健康；完成请求日志 alone 有盲区。","State-holding exhaustion detection must retain incomplete connections, age, byte progress, active or rejected connections, and external health; completion-only request logs have a blind spot.",["NJT-0199","NJS-0199-001","DET-000231"],["REF-000971","REF-000972","REF-000973"],"strongly-inferred","high"),
(981,"detection","输入成本放大检测需连接路由和请求长度/结构、每请求时延/错误、内部资源与健康结果；标准 HTTP 指标不提供每请求 CPU。","Input-cost amplification detection needs to join route and request length or structure, per-request duration or error, internal resources, and health outcome; standard HTTP metrics do not provide per-request CPU.",["NJT-0199","NJS-0199-002","DET-000231"],["REF-000973","REF-000974","REF-000975"],"strongly-inferred","high"),
(982,"mitigation","连接/阶段超时、最小数据率、输入/算法工作界限、隔离工作池和优雅降级可约束端点 DoS，但过严限制会拒绝慢速合法客户端或复杂业务输入。","Connection and stage timeouts, minimum data rates, input or algorithmic work bounds, isolated pools, and graceful degradation constrain endpoint DoS, while strict limits can reject slow legitimate clients or complex business input.",["NJT-0199","NJS-0199-001","NJS-0199-002"],["REF-000965","REF-000966","REF-000967","REF-000968","REF-000970"],"strongly-inferred","high"),
(983,"technique-relevance","攻击者完成主机、VM 或设备关机/重启并中断合法访问构成 Impact；单服务停止、阻止生命周期以维持立足点和无请求的崩溃具有不同直接对象。","An attacker completing shutdown or reboot of a host, VM, or device and interrupting legitimate access constitutes Impact; single-service stopping, inhibiting lifecycle to preserve a foothold, and crashes without a requester have different direct objects.",["NJT-0200"],["REF-000870","REF-000977","REF-000981"],"directly-observed","high"),
(984,"mechanism-mapping","系统接受的关机/重启路径与维护共享请求者、理由和 clean lifecycle 终态，状态/理由 alone 不能判定恶意。","A system-accepted shutdown or reboot path shares requester, reason, and clean lifecycle terminal state with maintenance, so state and reason alone cannot determine maliciousness.",["NJT-0200","NM-FD"],["REF-000977","REF-000978","REF-000980"],"strongly-inferred","medium"),
(985,"subtechnique-existence","Petya 创建一次性计划任务，将恶意 writer 与 10–60 分钟后由调度器执行的重启分离，任务定义和 Event 106 可恢复链。","Petya created a one-time scheduled task separating the malicious writer from a scheduler-executed reboot 10 to 60 minutes later; task definition and Event 106 can restore the chain.",["NJT-0200","NJS-0200-001","NM-ST"],["REF-000601"],"directly-observed","high"),
(986,"subtechnique-existence","ESXi 控制面可在 guest 外关闭运行 VM，使 guest 内传感器只看到失联，而 actor/action 留在 hypervisor 事件。","An ESXi control plane can power off running VMs from outside the guest, leaving guest sensors to see only disappearance while actor and action remain in hypervisor events.",["NJT-0200","NJS-0200-002","NM-BT"],["REF-000981","REF-000982","REF-000983"],"directly-observed","high"),
(987,"technique-boundary","T1529 需要攻击者控制的生命周期请求与完成的关机/重启；故障诱发 watchdog 重启首先属于 T1499，受限启动防御缺失属于 NJT-0172。","T1529 requires an attacker-controlled lifecycle request and completed shutdown or reboot; a fault-induced watchdog restart belongs first to T1499 and restricted-boot defensive omission to NJT-0172.",["NJT-0200"],["REF-000870","REF-000977"],"strongly-inferred","high"),
(988,"detection","本地请求、延迟任务和目标外管理面是三条不可互换的生命周期分析路径，需要不同字段和窗口。","Local requester, deferred task, and out-of-target management plane are three non-interchangeable lifecycle analytic paths requiring different fields and windows.",["NJT-0200","DET-000232"],["REF-000294","REF-000601","REF-000977","REF-000983"],"strongly-inferred","high"),
(989,"technique-relevance","账户访问移除要求既有合法主体在变更后实际无法认证或授权访问；凭据变化、边撤销或会话操作没有 post-state 失败时不完成 Impact。","Account Access Removal requires an existing legitimate principal to actually lose authentication or authorization after mutation; credential changes, edge removal, or session actions without post-state failure do not complete Impact.",["NJT-0201"],["REF-000984","REF-000103","REF-000167"],"directly-observed","high"),
(990,"subtechnique-existence","攻击者可保留账户实体和启用状态，却排他替换 owner 密码、MFA 或恢复方法，使粗粒度账户监控正常而合法 owner 登录失败。","An attacker can preserve account identity and enabled state while exclusively replacing owner password, MFA, or recovery methods, leaving coarse account monitoring normal while legitimate owner sign-in fails.",["NJT-0201","NJS-0201-001","NM-FD"],["REF-000167","REF-000985","REF-000986"],"directly-observed","high"),
(991,"subtechnique-existence","攻击者可移除角色、组、委托或 policy edge，使认证仍成功而资源求值拒绝合法 owner；身份和认证健康面因此看似正常。","An attacker can remove role, group, delegation, or policy edges so authentication still succeeds while resource evaluation denies the legitimate owner, leaving identity and authentication health apparently normal.",["NJT-0201","NJS-0201-002","NM-BT"],["REF-000103","REF-000985","REF-000986"],"directly-observed","high"),
(992,"detection","认证器置换检测需连接 directoryAudit old/new authenticator properties、发起者、审批与合法 owner 后续 sign-in failure；Graph signIn 可能不暴露精确方法 ID。","Authenticator-displacement detection needs to join directoryAudit old and new authenticator properties, initiator, approval, and later legitimate-owner sign-in failure; Graph signIn may not expose the exact method ID.",["NJT-0201","NJS-0201-001","DET-000233"],["REF-000985","REF-000986","REF-000376"],"strongly-inferred","high"),
(993,"detection","授权边撤除检测需保存角色/组/委托 before/after、资源 deny 与 break-glass 结果，并排除 offboarding、fraud response 和到期权限。","Authorization-edge eviction detection needs role, group, or delegation before and after state, resource denial, and break-glass outcome and must exclude offboarding, fraud response, and expired entitlement.",["NJT-0201","NJS-0201-002","DET-000233"],["REF-000103","REF-000985","REF-000986","REF-000987"],"strongly-inferred","high"),
(994,"mitigation","身份状态变更权限、可恢复旧值、多个独立 break-glass 路径和全路径恢复演练可降低租户 lockout，但批准系统或紧急账户同时受陷仍有残余风险。","Identity-state mutation authority, recoverable old values, multiple independent break-glass paths, and all-path recovery exercises reduce tenant lockout, while compromise of approval systems or emergency accounts leaves residual risk.",["NJT-0201","NJS-0201-001","NJS-0201-002"],["REF-000987","REF-000790"],"strongly-inferred","high"),
(995,"technique-relevance","磁盘擦除要求攻击者在块、物理盘或卷层破坏内容/结构并造成介质级不可用，区别于文件对象销毁、固件破坏和只读 raw access。","Disk Wipe requires adversary destruction of content or structure at block, physical-disk, or volume level with media-wide unavailability, distinct from file-object destruction, firmware corruption, and read-only raw access.",["NJT-0202"],["REF-000898","REF-000988","REF-000990"],"directly-observed","high"),
(996,"subtechnique-existence","少量写入 MBR/MFT 等关键元数据即可导致整个盘/卷无法启动或解释，使写入覆盖与可用性损失严重不对称。","Small writes to critical metadata such as MBR or MFT can make an entire disk or volume unbootable or uninterpretable, creating strong asymmetry between write coverage and availability loss.",["NJT-0202","NJS-0202-001","NM-BT"],["REF-000988","REF-000989"],"directly-observed","high"),
(997,"subtechnique-existence","ExPetr 等擦除器以勒索、安装 ID 或解密承诺呈现不可恢复磁盘破坏，使守方可能误判响应与恢复路径。","Wipers such as ExPetr present irreversible disk destruction through ransom, installation IDs, or decryption promises, causing defenders to misclassify response and recovery paths.",["NJT-0202","NJS-0202-002","NM-FD"],["REF-000989","REF-000990","REF-000991"],"directly-observed","high"),
(998,"detection","块破坏检测需连接原始设备打开/驱动、设备/扇区/长度/方向、结构清单、关键 metadata hash/CRC 和 mount/boot 结果；文件事件不提供这些偏移。","Block-destruction detection needs raw-device open or driver, device, sector, length, direction, structure inventory, critical-metadata hash or CRC, and mount or boot outcome; file events do not provide these offsets.",["NJT-0202","NJS-0202-001","DET-000105"],["REF-000992","REF-000993","REF-000994","REF-000840","REF-000366"],"strongly-inferred","high"),
(999,"detection","可恢复性伪装检测需把勒索工件、安装 ID/密钥来源、恢复代码语义与真实块状态连接；只有扩展名或勒索字条不能证明擦除。","Recoverability-pretext detection must join ransom artifacts, installation ID or key provenance, recovery-code semantics, and actual block state; extension or ransom note alone cannot prove wiping.",["NJT-0202","NJS-0202-002","DET-000234"],["REF-000989","REF-000990","REF-000991","REF-000475"],"strongly-inferred","high"),
(1000,"mitigation","最小 raw-write 权限、可信驱动、关键区间完整性、独立裸机映像和预text验证可限制擦除与误响应，但同控制面快照和过旧镜像不能保证恢复。","Least raw-write authority, trusted drivers, critical-extent integrity, independent bare-metal images, and pretext validation constrain wiping and wrong response, while same-plane snapshots and stale images do not ensure recovery.",["NJT-0202","NJS-0202-001","NJS-0202-002"],["REF-000988","REF-000989","REF-000990","REF-000995","REF-000996"],"strongly-inferred","high"),
]
for n,k,zh,en,subs,refs,mode,conf in CLAIMS:
 write(f"claims/CLM-{n:06d}-ta0040-batch-three.yaml",{"schema_version":"1.0.0","type":"claim","id":f"CLM-{n:06d}","claim_type":k,"statement_zh":zh,"statement_en":en,"subject_refs":subs,"evidence_refs":refs,"evidence_mode":mode,"confidence":conf,"status":"review"})

CASES=[
(283,"Petya 延迟计划重启","Petya Deferred Scheduled Reboot","Petya/NotPetya malware","2017",["Windows 企业环境"],["Windows enterprise environments"],"Microsoft 分析记录 Petya 创建一次性计划任务，在当前时间后随机 10–60 分钟执行 `shutdown.exe /r /f`。该事实支持 writer、任务定义和后来调度器重启之间的时间/主体分离；传播路径仍由其他 Case 负责。","Microsoft analysis records Petya creating a one-time task to execute `shutdown.exe /r /f` at a random time 10 to 60 minutes later. This supports temporal and actor separation among writer, task definition, and later scheduler reboot; propagation is owned by another Case.",["NJT-0200","NJS-0200-001"],["REF-000601"]),
(284,"Play 勒索软件从 ESXi 控制面关闭虚拟机","Play Ransomware Powers Off VMs from the ESXi Control Plane","Play ransomware actors","2023 advisory",["ESXi 虚拟化环境"],["ESXi virtualization environments"],"CISA 报告 Play 的 ESXi 变体枚举并关闭所有运行虚拟机，随后加密 VM 文件。关机造成 guest 可用性损失，actor/action 保留在 ESXi 控制面；后继文件加密需单独记录。","CISA reported the Play ESXi variant enumerating and powering off all running VMs before encrypting VM files. The power action causes guest availability loss while actor and action remain in the ESXi control plane; later file encryption requires separate recording.",["NJT-0200","NJS-0200-002"],["REF-000981"]),
(285,"DEV-0537 撤除其他全局管理员","DEV-0537 Evicts Other Global Administrators","DEV-0537/LAPSUS$","2022",["被 DEV-0537 入侵的 Microsoft Entra 租户"],["Microsoft Entra tenants compromised by DEV-0537"],"Microsoft 报告 DEV-0537 创建管理员后移除所有其他 Global Administrators，使组织失去租户管理访问。案例支持授权图边撤除导致合法 owner 资源访问被拒绝。","Microsoft reported DEV-0537 creating administrators and then removing all other Global Administrators, locking the organization out of tenant administration. The case supports authorization-edge eviction causing legitimate-owner resource denial.",["NJT-0201","NJS-0201-002"],["REF-000103"]),
(286,"Storm-2949 SSPR 认证器置换锁定","Storm-2949 SSPR Authenticator-Displacement Lockout","Storm-2949","2026",["云身份与 Microsoft Entra 环境"],["Cloud identity and Microsoft Entra environments"],"Microsoft 报告 Storm-2949 使用 SSPR 重置密码、移除原有认证方法并注册攻击者控制方法，阻止合法用户登录。账户实体仍存在但 owner 认证路径被排他置换。","Microsoft reported Storm-2949 using SSPR to reset a password, remove original authentication methods, and enroll attacker-controlled methods, preventing legitimate user sign-in. The account identity remained while owner authentication paths were exclusively displaced.",["NJT-0201","NJS-0201-001"],["REF-000167"]),
(287,"HermeticWiper 块层磁盘破坏","HermeticWiper Block-Level Disk Destruction","HermeticWiper operators","2022",["乌克兰 Windows 环境"],["Windows environments in Ukraine"],"ESET 与 SentinelOne 分析 HermeticWiper 借合法 EaseUS 驱动执行低层磁盘操作，破坏 MBR、MFT 及相关结构并导致启动失败。案例支持块层父行为和关键元数据最小写入轴。","ESET and SentinelOne analyzed HermeticWiper using legitimate EaseUS drivers for low-level disk operations, corrupting MBR, MFT, and related structures and causing boot failure. The case supports the block-level parent and critical-metadata minimal-write axis.",["NJT-0202","NJS-0202-001"],["REF-000988","REF-000989"]),
(288,"GigaWiper 分区重建与广泛擦除","GigaWiper Partition Reinitialization and Broad Wipe","GigaWiper operators","2026",["遭 GigaWiper 针对的 Windows 环境"],["Windows environments targeted by GigaWiper"],"Microsoft 报告 GigaWiper 枚举物理盘、重新初始化分区元数据并广泛覆写磁盘；其勒索样式路径未保存可恢复 key/IV。案例支持父级广泛擦除与可恢复性伪装边界。","Microsoft reported GigaWiper enumerating physical disks, reinitializing partition metadata, and broadly overwriting media, while its ransomware-like path did not preserve recoverable key or IV material. The case supports broad parent wiping and the recoverability-pretext boundary.",["NJT-0202","NJS-0202-002"],["REF-000990"]),
(289,"ExPetr 勒索外观下的不可恢复擦除","ExPetr Irrecoverable Wipe Under a Ransomware Appearance","ExPetr/NotPetya operators","2017",["ExPetr 全球受害环境"],["Environments affected globally by ExPetr"],"Kaspersky 证明 ExPetr 展示勒索和安装 ID，但 ID 为随机数据，无法生成磁盘解密所需信息，因此事件呈现与真实可恢复性冲突。","Kaspersky established that ExPetr displayed ransom and an installation ID, but the ID was random data unable to derive disk decryption information, creating a conflict between presentation and actual recoverability.",["NJT-0202","NJS-0202-002"],["REF-000991"]),
]
for n,zh,en,actor,tr,sz,se,dz,de,subs,refs in CASES:
 write(f"cases/CASE-{n:06d}-ta0040-batch-three.yaml",{"schema_version":"1.0.0","type":"case","id":f"CASE-{n:06d}","name_zh":zh,"name_en":en,"actor_or_campaign":actor,"subject_refs":subs,"description_zh":dz,"description_en":de,"time_range":tr,"target_sectors_zh":sz,"target_sectors_en":se,"evidence_refs":refs,"confidence":"high","status":"review"})

DECISIONS=[
("T1498","网络拒绝服务","Network Denial of Service","NJT-0198",["REF-000955","REF-000956","REF-000958","REF-000899"],"网络拒绝服务直接使网络链路、协议路径或边界容量无法承载合法通信。Niji 保留父结果并按来源拓扑适配为多源低贡献洪泛和响应源归因置换；ATT&CK 的直接/反射子项只作证据聚类。","Network Denial of Service directly prevents a link, protocol path, or boundary capacity from carrying legitimate traffic. Niji retains the result and adapts by source topology into multi-source low-contribution flooding and response-origin displacement; ATT&CK direct and reflection children remain evidence clusters only.","端点内部资源失败归 T1499；为攻击者任务消费带宽归 NJT-0189；botnet/C2 是前置控制。","Endpoint-internal failure belongs to T1499, bandwidth consumed for adversary work to NJT-0189, and botnet or C2 is precursor control."),
("T1499","端点拒绝服务","Endpoint Denial of Service","NJT-0199",["REF-000964","REF-000965","REF-000968","REF-000976"],"端点拒绝服务通过内部连接、工作槽位、CPU、内存、事件循环或缺陷触发造成服务不可用。Niji 按低速状态保持与小输入工作量放大划分原生子项，四个 ATT&CK 子项仅描述栈层与实现。","Endpoint Denial of Service causes unavailability through internal connection state, workers, CPU, memory, event loop, or triggered faults. Niji defines low-rate state holding and small-input work amplification as native children, while four ATT&CK children describe stack layers and implementation only.","有序服务停止归 NJT-0185，网络路径饱和归 T1498，为攻击者任务的资源消费归 NJT-0189；漏洞行为需有实际 availability 结果。","Orderly service stopping belongs to NJT-0185, network-path saturation to T1498, and resource consumption for attacker work to NJT-0189; exploitation needs an actual availability outcome."),
("T1529","系统关机或重启","System Shutdown/Reboot","NJT-0200",["REF-000870","REF-000601","REF-000977","REF-000981"],"攻击者控制系统接受的生命周期转换并造成主机、VM 或设备访问中断，属于 Impact。Niji 正式化延迟委托执行和目标外控制面两个观察变量；ATT&CK 无子项不限制开放搜索。","An attacker-controlled lifecycle transition accepted by the system and interrupting host, VM, or device access is Impact. Niji formalizes deferred delegated execution and out-of-target control plane as two observation variables; absence of ATT&CK children does not limit open search.","单服务停止归 NJT-0185；阻止关机以维持立足点归 NJT-0096；受限启动归 NJT-0172；无攻击者生命周期请求的 panic/watchdog 首先归 T1499。","Single-service stopping belongs to NJT-0185, inhibited shutdown preserving a foothold to NJT-0096, restricted boot to NJT-0172, and panic or watchdog without an attacker lifecycle request first to T1499."),
("T1531","移除账户访问","Account Access Removal","NJT-0201",["REF-000984","REF-000103","REF-000167","REF-000985","REF-000986"],"移除账户访问只有在既有合法主体实际无法认证或授权访问时完成。Niji 按账户身份保留但认证器被排他置换，以及认证仍成功但授权边被撤除两种观察差异划分。","Account Access Removal completes only when an existing legitimate principal actually loses authentication or authorized access. Niji divides by identity-preserving exclusive authenticator displacement and successful authentication followed by authorization-edge eviction.","新增攻击者访问状态归 NJT-0083，权限提升归 TA0004，会话级撤销不是持久 Impact；正常 offboarding、恢复和 fraud response 是反例。","Added attacker access state belongs to NJT-0083, privilege escalation to TA0004, and session-only revocation is not durable Impact; normal offboarding, recovery, and fraud response are counterexamples."),
("T1561","磁盘擦除","Disk Wipe","NJT-0202",["REF-000898","REF-000988","REF-000989","REF-000990","REF-000991"],"磁盘擦除在块、物理盘或卷层破坏内容与结构并造成介质级不可用。Niji 按少量关键元数据写入造成大范围损失，以及不可恢复擦除被包装为可解密勒索两个变量划分；ATT&CK 内容/结构子项不导入。","Disk Wipe destroys content and structure at block, physical-disk, or volume level and causes media-wide unavailability. Niji divides by small critical-metadata writes causing broad loss and irreversible wipe presented as decryptable ransomware; ATT&CK content and structure children are not imported.","文件/对象销毁归 NJT-0156，固件破坏归 NJT-0188，恢复对象归 NJT-0186，只读 raw access 归 NJT-0108；正常格式化/退役是反例。","File or object destruction belongs to NJT-0156, firmware corruption to NJT-0188, recovery objects to NJT-0186, and read-only raw access to NJT-0108; normal formatting or decommission is a counterexample."),
]
for aid,zh,en,result,refs,rz,re,sz,se in DECISIONS:
 write(f"matrix/tactics/TA0040-impact/decisions/DEC-TA0040-{aid}.yaml",{"schema_version":"1.1.0","type":"technique-decision","id":f"DEC-TA0040-{aid}","tactic_ref":"TA0040","candidate":{"source_type":"attack","source_attack_id":aid,"source_attack_version":"19.1","name_en":en,"name_zh":zh},"decision":"adapt","rationale_zh":rz,"rationale_en":re,"scope_notes_zh":sz,"scope_notes_en":se,"gap_statement_zh":None,"gap_statement_en":None,"original_attack_subtechniques_imported":False,"resulting_technique_ref":result,"evidence_refs":refs,"confidence":"high","review":{"status":"review","authors":["Niji Matrix Research"],"reviewers":[],"review_notes_zh":"第三批独立证据、准入和原生 taxonomy 主审完成，等待人工领域评审。","review_notes_en":"Batch-three independent evidence, admission, and native-taxonomy primary review are complete; human domain review remains."}})

