_m88=next((ROOT/"mitigations").glob("MIT-000088-*.yaml"));_d88=yaml.safe_load(_m88.read_text())
for _a in _d88["applications"]:
 if _a["target_ref"]=="NJS-0200-001":
  _a["use"]=PP(("对 shutdown 或 reboot 任务限制 writer 与 runtime authority，保存 definition digest、creator、next run、target、approval 和 expiry，并在未来触发前撤销异常定义。","Restrict writer and runtime authority for shutdown or reboot tasks, retain definition digest, creator, next run, target, approval, and expiry, and revoke anomalous definitions before future execution."),("关键系统只允许短期调度权限和双人批准，并把任务注册、调度器子进程、Event 1074、boot ID 与业务健康保存为不同权的长期谱系。","Critical systems permit only time-bound scheduling authority and dual approval and preserve task registration, scheduler child, Event 1074, boot ID, and business health as differently authorized long-lived lineage."))
  _a["expected_effect"]=PP(("调度对象准入和长期定义保留把原始 writer 与后来 lifecycle 结果重新连接，使 SYSTEM 或 scheduler runtime 不再掩盖最初决定。","Scheduler-object admission and long-term definition retention reconnect the original writer to the later lifecycle outcome so SYSTEM or scheduler runtime no longer obscures the initiating decision."),("异常未来 action 可在关机或重启发生前被发现、审批拒绝或撤销，关键业务的非预期中断范围和持续时间随之下降。","An anomalous future action can be detected, denied approval, or revoked before shutdown or reboot, reducing the scope and duration of unexpected interruption to critical business."))
  _a["limitations"]=PP(("合法补丁、安装、恢复和运维高度依赖同一调度器，审计缺口、TaskCache 或 provider 后端直接修改以及受陷 controller 仍可绕过治理。","Legitimate patching, installation, recovery, and operations rely heavily on the same scheduler, while audit gaps, direct TaskCache or provider-backend mutation, and compromised controllers can bypass governance."),("时钟变化、离线补跑、task ID 重用和紧急 authority 会改变实际触发时点或削弱 creator lineage，因此必须保留 definition digest、run instance 和外部审批。","Clock changes, offline catch-up, task ID reuse, and emergency authority can change actual trigger time or weaken creator lineage, requiring retention of definition digest, run instance, and external approval."))
_d88["lifecycle"]["modified"]=TODAY;_d88["lifecycle"]["version"]="0.3.0";_m88.write_text(yaml.safe_dump(_d88,allow_unicode=True,sort_keys=False,width=112),encoding="utf-8")

